def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if not line.strip():
            continue
        # Must contain '='
        if '=' not in line:
            raise ValueError("Missing '=' in line: " + str(line))
        # Split on first '=' only
        key, value = line.split('=', 1)
        # Strip whitespace from key and value
        key = key.strip()
        value = value.strip()
        # Reject empty key
        if not key:
            raise ValueError("Empty key in line: " + str(line))
        # Later duplicate keys win
        result[key] = value
    return result

def trim_history(messages, budget):
    # Validate budget is nonnegative
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate every message's cost is nonnegative
    for msg in messages:
        if msg["cost"] < 0:
            raise ValueError("all message costs must be nonnegative")

    # Find the longest contiguous suffix whose total cost fits in budget.
    # We work from the end backwards, accumulating cost.
    total = 0
    start = len(messages)  # start index of the suffix

    for i in range(len(messages) - 1, -1, -1):
        if total + messages[i]["cost"] <= budget:
            total += messages[i]["cost"]
            start = i
        else:
            break

    return list(messages[start:])

