def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = []
    for call in calls:
        cid = call['id']
        if cid in seen_ids:
            raise ValueError("Duplicate call id: " + str(cid))
        seen_ids.append(cid)

    # Build a dict of results by id (last one wins)
    result_map = {}
    for res in results:
        rid = res['id']
        result_map[rid] = res

    # Build output in call order
    output = []
    for call in calls:
        cid = call['id']
        if cid in result_map:
            res = result_map[cid]
            content = res.get('content', '')
            output.append({'id': cid, 'status': 'done', 'content': content})
        else:
            output.append({'id': cid, 'status': 'pending'})

    return output

