def parse_pairs(lines):
    result = {}
    for line in lines:
        # Skip blank lines
        if not line.strip():
            continue
        # Reject lines without '='
        if '=' not in line:
            raise ValueError("Missing '=' in line: " + line)
        # Split on first '=' only
        key, value = line.split('=', 1)
        # Strip whitespace from key and value
        key = key.strip()
        value = value.strip()
        # Reject empty key
        if not key:
            raise ValueError("Empty key in line: " + line)
        # Later duplicate keys win
        result[key] = value
    return result

def trim_history(messages, budget):
    # Validate budget is nonnegative
    if budget < 0:
        raise ValueError("budget must be nonnegative")

    # Validate every message's cost is nonnegative
    for msg in messages:
        if msg["cost"] < 0:
            raise ValueError("all message costs must be nonnegative")

    n = len(messages)
    if n == 0:
        return []

    # Work backwards from the end to find the longest suffix
    # whose total cost fits within budget.
    total = 0
    start = n  # default: empty suffix
    for i in range(n - 1, -1, -1):
        if total + messages[i]["cost"] <= budget:
            total += messages[i]["cost"]
            start = i
        else:
            break

    return list(messages[start:])

