def merge_tool_results(calls, results):
    # Check for duplicate call ids
    seen_ids = []
    for call in calls:
        call_id = call['id']
        if call_id in seen_ids:
            raise ValueError("Duplicate call id: " + str(call_id))
        seen_ids.append(call_id)

    # Build a map of result id -> result (last one wins)
    result_map = {}
    for result in results:
        result_id = result['id']
        # Only store results with ids that exist in calls
        if result_id in seen_ids:
            result_map[result_id] = result

    # Build output in call order
    output = []
    for call in calls:
        call_id = call['id']
        if call_id in result_map:
            result = result_map[call_id]
            content = result.get('content', '')
            output.append({'id': call_id, 'status': 'done', 'content': content})
        else:
            output.append({'id': call_id, 'status': 'pending'})

    return output

